create extension if not exists pgcrypto;
create type app_role as enum ('user','judge','admin');
create table profiles(id uuid primary key references auth.users on delete cascade, nickname text not null, platform text, region text, role app_role not null default 'user', status text not null default 'Unranked' check (status in ('Unranked','Pending','Ranked','Suspended')), created_at timestamptz default now());
create unique index profiles_nick_ci on profiles(lower(nickname));
create table pvp_modes(id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, active boolean default true);
create table rank_tiers(id uuid primary key default gen_random_uuid(), name text unique not null, sort_order int unique not null);
create table player_ranks(id uuid primary key default gen_random_uuid(), player_id uuid not null references profiles on delete cascade, mode_id uuid not null references pvp_modes, tier_id uuid not null references rank_tiers, verified_by uuid references profiles, verified_at timestamptz default now(), unique(player_id, mode_id));
create table rank_applications(id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, mode_id uuid not null references pvp_modes, desired_tier_id uuid not null references rank_tiers, platform text not null, region text, video_url text not null, comment text, status text not null default 'Pending' check (status in ('Pending','Under Review','Accepted','Rejected')), created_at timestamptz default now());
create unique index one_open_app on rank_applications(user_id, mode_id) where status in ('Pending','Under Review');
create table matches(id uuid primary key default gen_random_uuid(), mode_id uuid not null references pvp_modes, judge_id uuid not null references profiles, first_to int not null default 5, evidence_url text, played_at timestamptz default now());
create table match_participants(match_id uuid references matches on delete cascade, player_id uuid references profiles, score int not null default 0, primary key(match_id, player_id));
create table audit_logs(id bigint generated always as identity primary key, actor_id uuid, action text not null, target text, details jsonb, created_at timestamptz default now());
create index on player_ranks(mode_id, tier_id); create index on rank_applications(status);
create function is_staff() returns boolean language sql security definer stable as $$ select exists(select 1 from profiles where id=auth.uid() and role in ('judge','admin')) $$;
create function new_user() returns trigger language plpgsql security definer as $$ begin insert into profiles(id,nickname) values(new.id, coalesce(new.raw_user_meta_data->>'nickname','player_'||substr(new.id::text,1,6))); return new; end $$;
create trigger on_signup after insert on auth.users for each row execute function new_user();
alter table profiles enable row level security; alter table pvp_modes enable row level security; alter table rank_tiers enable row level security; alter table player_ranks enable row level security; alter table rank_applications enable row level security; alter table matches enable row level security; alter table match_participants enable row level security; alter table audit_logs enable row level security;
create policy pub_profiles on profiles for select using (true);
create policy own_profile on profiles for update using (id=auth.uid()) with check (id=auth.uid());
revoke update on profiles from authenticated, anon; grant update(platform, region) on profiles to authenticated;
create policy pub_modes on pvp_modes for select using (true);
create policy pub_tiers on rank_tiers for select using (true);
create policy pub_ranks on player_ranks for select using (true);
create policy staff_ranks on player_ranks for all using (is_staff()) with check (is_staff());
create policy pub_matches on matches for select using (true);
create policy staff_matches on matches for insert with check (is_staff() and judge_id=auth.uid());
create policy pub_parts on match_participants for select using (true);
create policy staff_parts on match_participants for insert with check (is_staff());
create policy own_apps_read on rank_applications for select using (user_id=auth.uid() or is_staff());
create policy own_apps_ins on rank_applications for insert with check (user_id=auth.uid() and status='Pending');
create policy staff_apps_upd on rank_applications for update using (is_staff());
create policy staff_audit_read on audit_logs for select using (is_staff());
insert into rank_tiers(name,sort_order) select r||' '||s, (row_number() over (order by o, d desc)) from (values('Bronze',1),('Silver',2),('Gold',3),('Elite',4)) a(r,o), (values('III',3),('II',2),('I',1)) b(s,d);
insert into pvp_modes(slug,name) values('sword','Sword PvP'),('mace','Mace PvP'),('axe','Axe PvP'),('crystal','Crystal PvP'),('pot','Pot PvP'),('uhc','UHC PvP');
